// Extract incoming farmer inquiry and detect primary intent
const body = $json.body || $json;
const prompt = (body.prompt || body.message || '').trim();
const crop = body.cropContext || body.crop || 'Wheat';
const state = body.state || (body.location && body.location.state) || 'Haryana';
const district = body.district || (body.location && body.location.district) || 'Karnal';
const lang = body.language || 'en';

const pLower = prompt.toLowerCase();
let intent = 'orchestrate'; // Default to full multi-tool orchestrator

const isCrop = /yellow|पीला|leaf|पत्ती|disease|रोग|rust|रतुआ|blight|झुलसा|pest|कीड़ा|spot|धब्बा/.test(pLower);
const isWeather = /weather|मौसम|rain|बारिश|spray|छिड़काव|wind|हवा|forecast|पूर्वानुमान/.test(pLower);
const isMandi = /mandi|मंडी|price|भाव|profit|मुनाफा|sell|बेचना|quintal|क्विंटल|rate/.test(pLower);
const isSoil = /soil|मिट्टी|khad|खाद|fertilizer|urea|यूरिया|dap|ph|saline|alkaline/.test(pLower);
const isSchemes = /scheme|योजना|pmfby|बीमा|claim|क्लेम|loss|नुकसान|hailstorm|ओलावृष्टि/.test(pLower);

// Single-domain routing or multi-tool orchestrator
const matchCount = [isCrop, isWeather, isMandi, isSoil, isSchemes].filter(Boolean).length;

if (matchCount > 1) {
  intent = 'orchestrate';
} else if (isCrop) {
  intent = 'crop_health';
} else if (isWeather) {
  intent = 'weather';
} else if (isMandi) {
  intent = 'mandi';
} else if (isSoil) {
  intent = 'soil';
} else if (isSchemes) {
  intent = 'schemes';
}

// Extract quantities and pricing if present
let quantityQuintals = 50;
const qMatch = pLower.match(/(\d+(?:\.\d+)?)\s*(?:quintals?|qtl|क्विंटल)/);
if (qMatch) quantityQuintals = parseFloat(qMatch[1]);

let expectedPrice = 2450;
const pMatch = pLower.match(/(?:rs\.?|inr|₹|भाव|दर|रेट|at)\s*[:=]?\s*(\d{3,5})/);
if (pMatch) expectedPrice = parseFloat(pMatch[1]);

return [{
  json: {
    prompt,
    crop,
    state,
    district,
    lang,
    intent,
    quantityQuintals,
    expectedPrice,
    rawPayload: body
  }
}];

