// Format consolidated response for webhook caller
const item = $json;

let responseBody = {};

if (item.integratedSynthesis) {
  // Full agent result
  responseBody = {
    status: 'success',
    workflow: 'n8n-kisan-culture-agent',
    requestId: item.requestId,
    timestamp: item.timestamp,
    toolsInvoked: item.toolsInvoked,
    synthesis: item.integratedSynthesis,
    actionRoadmap: item.actionRoadmap,
    plan: item.plan,
    toolOutputs: item.toolOutputs
  };
} else if (item.grossRevenue !== undefined) {
  // Mandi profit result
  responseBody = {
    status: 'success',
    workflow: 'n8n-kisan-culture-agent',
    toolsInvoked: ['mandi_advisor'],
    synthesis: `Mandi Calculation: For ${item.quantityQuintals} qtl of ${item.commodity}, Gross Revenue is ₹${item.grossRevenue.toLocaleString('en-IN')}, Total Deductions are ₹${item.totalExpenses.toLocaleString('en-IN')}, and Net In-Hand Realization is ₹${item.netReturn.toLocaleString('en-IN')} (Effective: ₹${item.effectivePricePerQtl}/qtl).`,
    calculation: item
  };
} else if (item.current && item.current.temperatureC !== undefined) {
  // Weather result
  responseBody = {
    status: 'success',
    workflow: 'n8n-kisan-culture-agent',
    toolsInvoked: ['weather_guardian'],
    synthesis: `Weather Intelligence for ${item.district}: Current temp is ${item.current.temperatureC}°C, wind speed is ${item.current.windSpeedKmph} km/h (${item.current.source}). Favorable spray window active after morning dew dries.`,
    telemetry: item
  };
} else if (item.rankedCauses) {
  // Crop health result
  responseBody = {
    status: 'success',
    workflow: 'n8n-kisan-culture-agent',
    toolsInvoked: ['crop_health'],
    synthesis: `Crop Pathology for ${item.crop}: Top identified cause is ${item.rankedCauses[0]?.name} (${item.rankedCauses[0]?.confidenceScore}% confidence). ${item.immediateSteps?.[0] || ''}`,
    diagnosis: item
  };
} else {
  responseBody = {
    status: 'success',
    workflow: 'n8n-kisan-culture-agent',
    data: item
  };
}

return [{ json: responseBody }];
